const primeiro = (n) => String(n || '').trim().split(/\s+/)[0] || '';

const as = $input.all().map((i) => i.json).filter((a) => a.contato_id);
if (!as.length) return [];
const linha = (a) => {
  const n = '*' + (a.nome || 'cliente').split(' ').slice(0, 2).join(' ') + '*';
  if (a.situacao === 'remarcou') {
